const CONTEXT_HINTS = [
  '절차', '프로세스', '리뷰 방식', '피드백 방식', '피드백', '전달 방식', '전달',
  '협업 방식', '협업', '작업 방식', '업무 흐름', '역할 분담', '담당 범위',
  '승인 방식', '승인', '완료 기준', '작업 순서', '적용 시점', '운영 원칙',
  '재작업', '반복 피드백', '커뮤니케이션 비용', '커뮤니케이션', '취합', '모아서',
  '한번에 전달', 'handoff', '병목', '방식 변경', '변경', '합의', '하기로',
];

const AGREEMENT_HINTS = [
  '합의했습니다', '합의함', '합의하기로', '결정했습니다', '결정하기로', '결정한다',
  '확정했습니다', '확정하기로', '하기로', '정했습니다', '정리했습니다', '적용합니다',
  '적용하기로', '진행하기로', '변경합니다', '변경하기로', '통일합니다',
  'go', '재작업 여부를 결정',
];

const SUGGESTION_ONLY = /(제안|좋을 것 같|어떨까요|어떻|의견|생각해봅시다|하면 좋겠습니다)/i;
const AGREEMENT = new RegExp(AGREEMENT_HINTS.map(escapeRegExp).join('|'), 'i');
const CONTEXT = new RegExp(CONTEXT_HINTS.map(escapeRegExp).join('|'), 'i');

function escapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function text(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function compact(value) {
  return text(value).toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '');
}

export function persistentContextSignal(value) {
  const content = text(value);
  if (!content || !CONTEXT.test(content)) return false;
  return AGREEMENT.test(content) && !(SUGGESTION_ONLY.test(content) && !AGREEMENT.test(content));
}

export function hasPersistentContextHint(value) {
  return CONTEXT.test(text(value));
}

export function persistentContextTopic(value) {
  const content = text(value).toLowerCase();
  if (/(리뷰|피드백|시안|정합성)/i.test(content)) return 'review_feedback';
  if (/(전달|handoff|취합|모아서|한번에)/i.test(content)) return 'handoff';
  if (/(승인|go|재작업 여부)/i.test(content)) return 'approval';
  if (/(완료 기준|검증|qa|품질)/i.test(content)) return 'quality';
  if (/(역할|담당 범위|협업)/i.test(content)) return 'roles';
  if (/(절차|프로세스|업무 흐름|작업 방식|운영 원칙)/i.test(content)) return 'process';
  return 'workflow';
}

function threadKey(message) {
  return message?.threadTs || message?.ts || message?.url || null;
}

function latestThreadTimestamp(messages) {
  return [...messages].sort((left, right) => String(right.time || '').localeCompare(String(left.time || '')))[0]?.time || null;
}

export function extractPersistentContexts({ channel, messages = [], recentDays = 7, projectName = null, now = Date.now() }) {
  const recentCutoff = now - Number(recentDays || 0) * 86400_000;
  const threads = new Map();
  for (const message of messages) {
    const timestamp = Date.parse(message.time || '') || 0;
    if (timestamp && timestamp >= recentCutoff) continue;
    const key = threadKey(message);
    if (!key) continue;
    const bucket = threads.get(key) || [];
    bucket.push(message);
    threads.set(key, bucket);
  }

  const contexts = [];
  for (const threadMessages of threads.values()) {
    const ordered = [...threadMessages].sort((left, right) => String(left.time || '').localeCompare(String(right.time || '')));
    const combined = ordered.map(message => [message.parentText, message.text].filter(Boolean).join(' · ')).join(' · ');
    if (!persistentContextSignal(combined)) continue;
    const agreementMessage = [...ordered].reverse().find(message => AGREEMENT.test(text(message.text)));
    const anchor = agreementMessage || ordered.at(-1) || ordered[0];
    const parent = ordered.find(message => !message.parentText) || ordered[0];
    const excerpt = text(ordered.map(message => {
      const body = text(message.text);
      return message.parentText && body !== text(message.parentText) ? body : body;
    }).filter(Boolean).join(' · ')).slice(0, 420);
    const projectMatch = projectName ? compact(combined).includes(compact(projectName)) : false;
    contexts.push({
      source: 'slack',
      evidenceRole: 'persistent_context',
      timestamp: latestThreadTimestamp(ordered),
      title: `#${channel} · 업무 방식 합의`,
      excerpt,
      url: anchor.url || parent.url || null,
      attention: false,
      attentionType: null,
      topicKey: persistentContextTopic(combined),
      projectMatch,
      threadKey: threadKey(parent),
    });
  }

  const unique = new Map();
  for (const context of contexts) {
    const key = `${context.topicKey}|${context.threadKey || context.url || context.excerpt}`;
    if (!unique.has(key)) unique.set(key, context);
  }
  return [...unique.values()]
    .sort((left, right) => String(right.timestamp || '').localeCompare(String(left.timestamp || '')))
    .slice(0, 8);
}

export function persistentContextPatterns() {
  return { hints: [...CONTEXT_HINTS], agreements: [...AGREEMENT_HINTS] };
}

const API = 'https://slack.com/api';
import { extractPersistentContexts, hasPersistentContextHint } from './slack-context.mjs';

export function slackMessageUrl(channelId, ts, threadTs = null) {
  const messageTs = String(ts || '').replace('.', '');
  if (!channelId || !messageTs) return null;
  const base = `https://slack.com/archives/${encodeURIComponent(channelId)}/p${messageTs}`;
  return threadTs
    ? `${base}?thread_ts=${encodeURIComponent(threadTs)}&cid=${encodeURIComponent(channelId)}`
    : base;
}

async function call(method, params = {}) {
  const qs = new URLSearchParams(params);
  const res = await fetch(`${API}/${method}?${qs}`, {
    headers: { Authorization: `Bearer ${process.env.SLACK_TOKEN}` },
  });
  const json = await res.json();
  if (!json.ok) {
    if (json.error === 'ratelimited') {
      await new Promise(r => setTimeout(r, 30_000));
      return call(method, params);
    }
    throw new Error(`Slack ${method}: ${json.error}`);
  }
  return json;
}

let channelMap = null; // name → id
export async function getChannelId(name) {
  if (!channelMap) {
    channelMap = new Map();
    let cursor;
    do {
      const res = await call('conversations.list', {
        types: 'public_channel,private_channel', limit: 200,
        ...(cursor ? { cursor } : {}),
      });
      for (const c of res.channels) channelMap.set(c.name, c.id);
      cursor = res.response_metadata?.next_cursor || null;
    } while (cursor);
  }
  return channelMap.get(name) || null;
}

let userMap = null; // id → display name
async function userName(id) {
  if (!userMap) {
    userMap = new Map();
    let cursor;
    do {
      const res = await call('users.list', { limit: 200, ...(cursor ? { cursor } : {}) });
      for (const u of res.members) userMap.set(u.id, u.profile?.display_name || u.real_name || u.name);
      cursor = res.response_metadata?.next_cursor || null;
    } while (cursor);
  }
  return userMap.get(id) || id;
}

async function threadReplies(channelId, parent) {
  const replies = [];
  let cursor;
  do {
    const res = await call('conversations.replies', {
      channel: channelId, ts: parent.ts, limit: 200, ...(cursor ? { cursor } : {}),
    });
    for (const message of res.messages || []) {
      if (message.ts === parent.ts || message.subtype || !message.text) continue;
      replies.push({
        ts: message.ts,
        time: new Date(Number(message.ts) * 1000).toISOString(),
        user: await userName(message.user),
        text: message.text.slice(0, 600),
        parentText: parent.text,
        threadTs: parent.ts,
        url: slackMessageUrl(channelId, message.ts, parent.ts),
        replies: 0,
        reactions: (message.reactions || []).reduce((total, reaction) => total + reaction.count, 0),
      });
    }
    cursor = res.response_metadata?.next_cursor || null;
  } while (cursor);
  return replies;
}

async function channelParents(channelId, oldest) {
  const messages = [];
  let cursor;
  do {
    const res = await call('conversations.history', {
      channel: channelId, oldest, limit: 200, ...(cursor ? { cursor } : {}),
    });
    for (const m of res.messages) {
      if (m.subtype || !m.text) continue;
      messages.push({
        ts: m.ts,
        time: new Date(Number(m.ts) * 1000).toISOString(),
        user: await userName(m.user),
        text: m.text.slice(0, 600),
        url: slackMessageUrl(channelId, m.ts),
        replies: m.reply_count || 0,
        reactions: (m.reactions || []).reduce((a, r) => a + r.count, 0),
      });
    }
    cursor = res.response_metadata?.next_cursor || null;
  } while (cursor);
  return messages;
}

// Fetches the normal recent window and a separate, small historical context set.
// Historical replies are loaded only for parents that contain workflow signals.
export async function channelHistoryWithContext(channelName, recentDays, historicalDays = 45, projectName = null) {
  const id = await getChannelId(channelName);
  if (!id) return { channel: channelName, error: 'channel_not_found', messages: [], persistentContexts: [] };
  const now = Date.now();
  const recentCutoff = now - Number(recentDays || 0) * 86400_000;
  const historicalCutoff = now - Number(historicalDays || 45) * 86400_000;
  const parents = await channelParents(id, (historicalCutoff / 1000).toFixed(0));
  const recentParents = parents.filter(message => Date.parse(message.time) >= recentCutoff);
  const historicalParents = parents.filter(message => Date.parse(message.time) < recentCutoff && hasPersistentContextHint(message.text));
  const recentReplies = [];
  for (const message of recentParents.filter(item => item.replies > 0)) recentReplies.push(...await threadReplies(id, message));
  const historicalReplies = [];
  const historicalWarnings = [];
  for (const message of historicalParents.filter(item => item.replies > 0)) {
    try { historicalReplies.push(...await threadReplies(id, message)); }
    catch (error) { historicalWarnings.push(error.message); }
  }
  const recentMessages = [...recentParents, ...recentReplies].sort((a, b) => a.ts.localeCompare(b.ts));
  const historicalMessages = [...historicalParents, ...historicalReplies].sort((a, b) => a.ts.localeCompare(b.ts));
  return {
    channel: channelName,
    messages: recentMessages,
    persistentContexts: extractPersistentContexts({
      channel: channelName,
      messages: historicalMessages,
      recentDays: 0,
      projectName,
      now: Date.now() + 1,
    }),
    historicalWarnings,
  };
}

// 최근 N일 채널 메시지 (스레드 원문만, 봇/시스템 메시지 제외)
export async function channelHistory(channelName, days) {
  const id = await getChannelId(channelName);
  if (!id) return { channel: channelName, error: 'channel_not_found', messages: [] };
  const oldest = (Date.now() / 1000 - days * 86400).toFixed(0);
  const messages = [];
  let cursor;
  do {
    const res = await call('conversations.history', {
      channel: id, oldest, limit: 200, ...(cursor ? { cursor } : {}),
    });
    for (const m of res.messages) {
      if (m.subtype || !m.text) continue;
      messages.push({
        ts: m.ts,
        time: new Date(Number(m.ts) * 1000).toISOString(),
        user: await userName(m.user),
        text: m.text.slice(0, 600),
        url: slackMessageUrl(id, m.ts),
        replies: m.reply_count || 0,
        reactions: (m.reactions || []).reduce((a, r) => a + r.count, 0),
      });
    }
    cursor = res.response_metadata?.next_cursor || null;
  } while (cursor);
  const replies = [];
  for (const message of messages.filter(item => item.replies > 0)) {
    replies.push(...await threadReplies(id, message));
  }
  messages.push(...replies);
  messages.sort((a, b) => a.ts.localeCompare(b.ts));
  return { channel: channelName, messages };
}

import { classifyExecutionAttention } from './execution-attention.mjs';
import {
  matchedExcerpt, matches, meetingSourceTerms, norm, sourceTerms, tokenFrequencies,
} from './spec-source-matcher.mjs';

const CLOSED = new Set(['완료', '일시 정지', '정지', '중단']);

function excerpt(value, limit = 220) {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  return text.length > limit ? `${text.slice(0, limit - 1)}…` : text;
}

function slackPlainText(value) {
  return String(value || '')
    .replace(/<https?:\/\/[^>|]+\|([^>]+)>/g, '$1')
    .replace(/<https?:\/\/[^>]+>/g, '')
    .replace(/<@[^>]+>/g, '담당자')
    .replace(/<![^>|]+\|([^>]+)>/g, '$1')
    .replace(/[*_~`]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function meetingExcerpt(meeting, terms) {
  const content = String(meeting.content || meeting.title || '');
  const segments = content
    .split(/\r?\n|(?<=[.!?])\s+/)
    .map(segment => segment.replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  const attention = segments
    .map((segment, index) => ({ segment, index, classification: classifyExecutionAttention(segment) }))
    .filter(({ segment, classification }) => classification
      && (matches(meeting.title, terms) || matches(segment, terms)))
    .sort((left, right) => Number(matches(right.segment, terms)) - Number(matches(left.segment, terms)) || left.index - right.index)[0];
  if (attention) {
    const context = `${attention.segment} · 회의: ${meeting.title}`;
    return {
      excerpt: excerpt(context, 260),
      attention: true,
      attentionType: attention.classification.type,
      attentionAction: attention.classification.action,
    };
  }
  return { excerpt: excerpt(matchedExcerpt(content, terms)), attention: false, attentionType: null, attentionAction: null };
}

function statusSummary(tasks) {
  const ordered = ['진행 중', '확인 요청', '검토중', '추가 진행', '진행 예정', '시작 전'];
  const counts = new Map();
  for (const task of tasks) counts.set(task.status || '상태 미정', (counts.get(task.status || '상태 미정') || 0) + 1);
  return [...counts.entries()]
    .sort((left, right) => {
      const leftOrder = ordered.indexOf(left[0]);
      const rightOrder = ordered.indexOf(right[0]);
      return (leftOrder < 0 ? 99 : leftOrder) - (rightOrder < 0 ? 99 : rightOrder);
    })
    .map(([status, count]) => `${status} ${count}건`)
    .join(' · ');
}

function teamSummary(tasks) {
  const counts = new Map();
  for (const task of tasks) counts.set(task.team || '팀 미지정', (counts.get(task.team || '팀 미지정') || 0) + 1);
  return [...counts.entries()]
    .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0], 'ko'))
    .map(([team, count]) => `${team} ${count}`)
    .join(' · ');
}

function fallbackSummary(spec) {
  const tasks = (spec.tasks || []).filter(task => !CLOSED.has(task.status));
  if (!tasks.length) return '현재 표시할 활성 작업항목이 없습니다.';
  const states = statusSummary(tasks);
  const teams = teamSummary(tasks);
  return `활성 작업 ${tasks.length}건은 ${states || '상태 미정'}입니다.${teams ? ` 파트별로는 ${teams}입니다.` : ''}`;
}

function fallbackBlockers(spec) {
  const overdue = (spec.tasks || []).filter(task => task.overdueDays > 0);
  const review = (spec.tasks || []).filter(task => ['확인 요청', '검토중'].includes(task.status));
  const blockers = [];
  if (overdue.length) blockers.push(`기한 초과 ${overdue.length}건: ${overdue.slice(0, 2).map(task => task.title).join(', ')}`);
  if (review.length) blockers.push(`확인 대기 ${review.length}건: ${review.slice(0, 2).map(task => task.title).join(', ')}`);
  return blockers;
}

function fallbackNextAction(spec) {
  const tasks = spec.tasks || [];
  if (tasks.some(task => task.overdueDays > 0)) return '기한 초과 작업의 지연 사유와 변경 일정을 먼저 확인합니다.';
  if (tasks.some(task => ['확인 요청', '검토중'].includes(task.status))) return '확인 요청과 검토중 작업의 승인·수정 여부를 정리합니다.';
  if (tasks.some(task => task.status === '진행 중')) return '진행 중 작업의 다음 완료 지점과 필요한 지원을 확인합니다.';
  if (tasks.some(task => ['시작 전', '진행 예정'].includes(task.status))) return '시작 전·진행 예정 작업의 착수 조건과 담당 일정을 확인합니다.';
  return null;
}

function notionEvidence(spec) {
  const latest = [...(spec.tasks || [])]
    .filter(task => task.notionUpdatedAt)
    .sort((left, right) => String(right.notionUpdatedAt).localeCompare(String(left.notionUpdatedAt)))[0];
  if (latest) {
    return {
      source: 'notion',
      timestamp: latest.notionUpdatedAt,
      title: latest.title,
      excerpt: `${latest.status || '상태 미정'} · 담당 ${(latest.assignees || []).join(', ') || '미지정'}`,
      url: latest.url || spec.url || null,
    };
  }
  return spec.url ? {
    source: 'notion', timestamp: null, title: spec.title,
    excerpt: `상위 작업 상태 ${spec.status || '미정'}`, url: spec.url,
  } : null;
}

function slackEvidence(channels, terms) {
  const candidates = (channels || []).flatMap(channel => (channel.messages || [])
    .filter(message => matches(`${message.parentText || ''}\n${message.text || ''}`, terms))
    .map(message => {
      const reply = slackPlainText(message.text);
      const parent = message.parentText ? slackPlainText(matchedExcerpt(message.parentText, terms)) : '';
      const classification = classifyExecutionAttention([reply, parent].filter(Boolean).join(' · '));
      return {
        source: 'slack', evidenceRole: 'recent_execution', timestamp: message.time || null,
        title: `#${channel.channel}${message.user ? ` · ${message.user}` : ''}`,
        // Replies carry the newest execution state. Keep them before parent
        // context so the remote excerpt budget is not consumed by Notion URLs.
        excerpt: excerpt([reply, parent && parent !== reply ? `맥락: ${parent}` : ''].filter(Boolean).join(' · ')),
        url: message.url || null,
        attention: Boolean(classification),
        attentionType: classification?.type || null,
        attentionAction: classification?.action || null,
        threadKey: norm(message.parentText || message.text),
      };
    }));
  const latestByThread = new Map();
  for (const candidate of candidates) {
    const key = candidate.threadKey || candidate.url || `${candidate.timestamp}|${candidate.excerpt}`;
    const previous = latestByThread.get(key);
    if (!previous || String(candidate.timestamp || '') > String(previous.timestamp || '')) latestByThread.set(key, candidate);
  }
  return [...latestByThread.values()]
    .map(({ threadKey, ...item }) => item)
    .sort((left, right) => Number(right.attention) - Number(left.attention)
      || String(right.timestamp || '').localeCompare(String(left.timestamp || '')))
    .slice(0, 2);
}

function meetingEvidence(meetings, terms) {
  return (meetings || [])
    .filter(meeting => matches(`${meeting.title || ''}\n${meeting.content || ''}`, terms))
    .map(meeting => {
      const extracted = meetingExcerpt(meeting, terms);
      return {
        source: 'meeting', evidenceRole: 'recent_execution', timestamp: meeting.date || null, title: meeting.title,
        excerpt: extracted.excerpt, url: meeting.url || null, attention: extracted.attention,
        attentionType: extracted.attentionType, attentionAction: extracted.attentionAction,
      };
    })
    .sort((left, right) => Number(right.attention) - Number(left.attention)
      || String(right.timestamp || '').localeCompare(String(left.timestamp || '')))
    .slice(0, 2);
}

function attentionNextAction(evidence) {
  return evidence.find(item => item.attention)?.attentionAction || null;
}

function gitEvidence(commits, spec, terms) {
  const taskIds = new Set((spec.tasks || []).map(task => task.id));
  return (commits || [])
    .filter(commit => (commit.workItemId && taskIds.has(commit.workItemId)) || matches(commit.message, terms))
    .map(commit => ({
      source: 'git', evidenceRole: 'recent_execution', timestamp: commit.committedAt || null,
      title: `${commit.shortHash || String(commit.hash || '').slice(0, 8)} · ${commit.author || '작성자 미상'}`,
      excerpt: excerpt(commit.message), url: commit.url || null,
    }))
    .sort((left, right) => String(right.timestamp || '').localeCompare(String(left.timestamp || '')))
    .slice(0, 2);
}

function roleTerms(spec) {
  const roles = new Set();
  for (const task of spec.tasks || []) {
    const source = `${task.team || ''} ${task.title || ''}`;
    for (const role of ['아트', '디자인', 'UI', 'UX', '개발', '기획', 'QA', '테크', '리소스', '클라이언트']) {
      if (source.toLowerCase().includes(role.toLowerCase())) roles.add(norm(role));
    }
  }
  return roles;
}

function persistentContextRelevant(context, project, spec, frequencies) {
  const content = `${context.title || ''}\n${context.excerpt || ''}`;
  const terms = sourceTerms(spec, frequencies);
  if (matches(content, terms)) return true;
  if (!context.projectMatch || !/(절차|프로세스|리뷰|피드백|협업|전달|handoff|역할|완료 기준|작업 방식|운영 원칙|재작업|취합|승인)/i.test(content)) return false;
  const roles = roleTerms(spec);
  return [...roles].some(role => content.toLowerCase().includes(role));
}

function persistentContextSuperseded(context, newerEvidence = []) {
  const topicPattern = {
    review_feedback: /리뷰|피드백|시안|정합성/i,
    handoff: /전달|handoff|취합|모아서|한번에/i,
    approval: /승인|go|재작업/i,
    quality: /완료 기준|검증|qa|품질/i,
    roles: /역할|담당 범위|협업/i,
    process: /절차|프로세스|업무 흐름|작업 방식|운영 원칙/i,
    workflow: /방식|업무|프로세스/i,
  }[context.topicKey] || /방식|변경|프로세스/i;
  return newerEvidence.some(item => {
    const newer = Date.parse(item.timestamp || '') > Date.parse(context.timestamp || '');
    return newer && topicPattern.test(item.excerpt || '') && /(변경|새로운|대체|현재는|이후|폐기|다시 정리)/i.test(item.excerpt || '');
  });
}

function persistentContextEvidence(contexts, project, spec, frequencies, newerEvidence = []) {
  const relevant = (contexts || []).filter(context => persistentContextRelevant(context, project, spec, frequencies));
  const latestByTopic = new Map();
  for (const context of relevant) {
    if (persistentContextSuperseded(context, newerEvidence)) continue;
    const key = context.topicKey || context.url || context.excerpt;
    const previous = latestByTopic.get(key);
    if (!previous || String(context.timestamp || '') > String(previous.timestamp || '')) latestByTopic.set(key, context);
  }
  return [...latestByTopic.values()]
    .sort((left, right) => String(right.timestamp || '').localeCompare(String(left.timestamp || '')))
    .slice(0, 2)
    .map(context => ({
      source: 'slack', evidenceRole: 'persistent_context', timestamp: context.timestamp || null,
      title: context.title || 'Slack · 현재 업무 방식 맥락', excerpt: context.excerpt || '',
      url: context.url || null, attention: false, attentionType: null,
    }));
}

export function buildSpecInsights({ project, slackChannels = [], persistentContexts = [], meetings = [], commits = [] }) {
  const specs = (project.specs || []).filter(spec => (spec.tasks || []).length > 0);
  const frequencies = tokenFrequencies(specs);
  return specs.map(spec => {
    const terms = sourceTerms(spec, frequencies);
    const meetingTerms = meetingSourceTerms(spec, frequencies);
    const notion = notionEvidence(spec);
    const slackForSpec = slackEvidence(slackChannels, terms);
    const meetingsForSpec = meetingEvidence(meetings, meetingTerms);
    const currentContextEvidence = [...slackForSpec, ...meetingsForSpec];
    const currentPersistentForSpec = persistentContextEvidence(persistentContexts, project, spec, frequencies, currentContextEvidence);
    const evidence = [
      ...(notion ? [notion] : []),
      ...slackForSpec,
      ...currentPersistentForSpec,
      ...meetingsForSpec,
      ...gitEvidence(commits, spec, terms),
    ].sort((left, right) => String(right.timestamp || '').localeCompare(String(left.timestamp || '')));
    const stateBlockers = fallbackBlockers(spec);
    const sourceAttention = [...slackForSpec, ...meetingsForSpec].filter(item => item.attention);
    const blockers = [...stateBlockers, ...sourceAttention.map(item => item.excerpt)]
      .filter((item, index, rows) => rows.indexOf(item) === index)
      .slice(0, 3);
    const stateNextAction = fallbackNextAction(spec);
    const sourceNextAction = attentionNextAction(sourceAttention);
    return {
      specId: spec.id,
      title: spec.title,
      summary: fallbackSummary(spec),
      blockers,
      nextAction: sourceNextAction || stateNextAction,
      evidence,
    };
  });
}

const GENERIC_TERMS = new Set([
  '버그', '버그수정', '개발', '기획', '아트', '확인', '작업', '작업들', '수정', '개선',
  '대응', '적용', '테스트', '시스템', '추가', '기능', '일감', '관련', '진행', '완료',
  '요청', '제안', '현상', '대한', '버전', '방법', '변경', '아이디어', '검토',
  '라이브', '이벤트', '리소스', '소스', '컨셉', '팝업', '리뷰', '피드백', '제안서', 'ui', 'ux',
  '스테이지', '신규', '정리', '내용', '반영',
]);
const NUMBERED_TOPIC_TERMS = new Set(['스테이지', 'stage', '챕터', 'chapter', '월드', 'world', '레벨', 'level']);

export function norm(value) {
  return String(value || '').toLowerCase().replace(/<[^>]+>/g, '').replace(/[^\p{L}\p{N}]+/gu, '');
}

function titleTokens(value) {
  const rawTokens = String(value || '').toLowerCase().match(/[\p{L}\p{N}]+/gu)?.map(norm) || [];
  const numberedTopics = rawTokens.flatMap((token, index) =>
    NUMBERED_TOPIC_TERMS.has(token) && /^\d+$/.test(rawTokens[index + 1] || '') ? [`${token}${rawTokens[index + 1]}`] : []);
  const descriptiveTokens = rawTokens.filter(token => token.length >= 2
      && !GENERIC_TERMS.has(token)
      && !/^(?:sprint|sp|스프린트)\d+$/i.test(token)
      && !/^\d+$/.test(token));
  return [...new Set([...numberedTopics, ...descriptiveTokens])];
}

export function tokenFrequencies(specs) {
  const frequencies = new Map();
  for (const spec of specs) {
    const tokens = new Set([spec.title, ...(spec.tasks || []).map(task => task.title)].flatMap(titleTokens));
    for (const token of tokens) frequencies.set(token, (frequencies.get(token) || 0) + 1);
  }
  return frequencies;
}

export function sourceTerms(spec, frequencies) {
  const titleTerms = [spec.title, ...(spec.tasks || []).map(task => task.title)]
    .map(value => {
      const full = norm(value);
      const candidates = [...new Set(titleTokens(value).filter(token => (frequencies.get(token) || 0) <= 1))];
      const tokens = candidates.filter(token => !candidates.some(other => other !== token && other.includes(token)));
      return {
        full: full.length >= 4 && !GENERIC_TERMS.has(full) ? full : null,
        tokens,
      };
    })
    .filter(term => term.full || term.tokens.length);
  const identityTerms = [spec.id, ...(spec.tasks || []).map(task => task.id)]
    .map(value => String(value || '').toLowerCase().replace(/[^a-z0-9]/g, ''))
    .filter(value => value.length >= 16)
    .map(identifier => ({ full: null, tokens: [], identifier }));
  return [...titleTerms, ...identityTerms];
}

export function meetingSourceTerms(spec, frequencies) {
  const specIdentity = sourceTerms({ id: spec.id, title: spec.title, tasks: [] }, frequencies);
  const taskTokenCounts = new Map();
  for (const task of spec.tasks || []) {
    for (const token of new Set(titleTokens(task.title))) {
      taskTokenCounts.set(token, (taskTokenCounts.get(token) || 0) + 1);
    }
  }
  const recurringCandidates = [...taskTokenCounts.entries()]
    .filter(([token, count]) => count >= 2 && (frequencies.get(token) || 0) <= 1)
    .map(([token]) => token);
  const recurringTokens = recurringCandidates
    .filter(token => !recurringCandidates.some(other => other !== token && other.includes(token)));
  const taskIdentifiers = (spec.tasks || [])
    .map(task => String(task.id || '').toLowerCase().replace(/[^a-z0-9]/g, ''))
    .filter(identifier => identifier.length >= 16)
    .map(identifier => ({ full: null, tokens: [], identifier }));
  return [
    ...specIdentity,
    ...(recurringTokens.length >= 2 ? [{ full: null, tokens: recurringTokens }] : []),
    ...taskIdentifiers,
  ];
}

function includesNearKoreanToken(normalized, token) {
  if (token.length < 3 || !/^[가-힣]+$/.test(token)) return false;
  for (let index = 0; index <= normalized.length - token.length; index += 1) {
    const candidate = normalized.slice(index, index + token.length);
    let differences = 0;
    for (let offset = 0; offset < token.length && differences <= 1; offset += 1) {
      if (candidate[offset] !== token[offset]) differences += 1;
    }
    if (differences <= 1) return true;
  }
  return false;
}

export function matches(text, terms) {
  const normalized = norm(text);
  const identifiers = String(text || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  return terms.some(term => {
    if (term.identifier && identifiers.includes(term.identifier)) return true;
    if (term.full && normalized.includes(term.full)) return true;
    const exactHits = term.tokens.filter(token => normalized.includes(token));
    if (exactHits.length >= 2 || exactHits.some(token => token.length >= 4)) return true;
    const fuzzyHits = term.tokens.filter(token => !normalized.includes(token) && includesNearKoreanToken(normalized, token));
    return exactHits.length >= 1 && fuzzyHits.length >= 1;
  });
}

export function matchedExcerpt(value, terms) {
  const text = String(value || '');
  const matchedLine = text.split(/\r?\n/).map(line => line.trim()).find(line => line && matches(line, terms));
  return matchedLine || text;
}

import { createHash, randomUUID, timingSafeEqual } from 'node:crypto';
import {
  applyGlobalSprintScope,
  legacyGlobalSprintScope,
  parseSprintInput,
  resolveSprintScope,
  scopeSignature,
  buildSprintOverview,
} from '../public/sprint-policy.js';

export const SETTINGS_PREFIX = 'sprint-settings:';
const KIND = 'MOLIP_GLOBAL_SPRINT_SETTINGS_V2';
const LEGACY_KIND = 'MOLIP_SPRINT_SETTINGS_V1';
const text = value => [{ type: 'text', text: { content: String(value) } }];
const plain = value => (value?.rich_text || value?.title || []).map(item => item.plain_text || item.text?.content || '').join('');
const error = (message, statusCode = 400) => Object.assign(new Error(message), { statusCode });
const hash = value => createHash('sha256').update(value).digest('hex');

export function settingsWriteAuthorized(request, token = process.env.SPRINT_SETTINGS_TOKEN) {
  const supplied = String(request.headers?.authorization || '');
  if (!token || token.length < 24 || !supplied.startsWith('Bearer ')) return false;
  return timingSafeEqual(Buffer.from(hash(supplied.slice(7))), Buffer.from(hash(token)));
}
export function settingsOriginAllowed(request) {
  const origin = request.headers?.origin;
  if (!origin) return true;
  try { return new URL(origin).host === String(request.headers.host || ''); } catch { return false; }
}

export async function readSprintSettings({ databaseId, query } = {}) {
  query ||= (await import('./notion.mjs')).queryDatabase;
  const pages = await query(databaseId, { property: 'run_id', rich_text: { starts_with: SETTINGS_PREFIX } });
  const records = [];
  const legacyRecords = [];
  for (const page of pages) {
    try {
      const record = JSON.parse(plain(page.properties?.payload));
      if (record.kind === KIND) {
        if (!['selected', 'all', 'unset'].includes(record.mode) || typeof record.input !== 'string' || !Array.isArray(record.sprints)
          || typeof record.revision !== 'string' || !Number.isFinite(Date.parse(record.changedAt))) throw Error('invalid');
        records.push(record);
      } else if (record.kind === LEGACY_KIND) {
        legacyRecords.push(record);
      }
    } catch {
      throw error('스프린트 설정 기록을 읽을 수 없습니다. 이전 값으로 임의 대체하지 않습니다.', 503);
    }
  }
  records.sort((a, b) => b.changedAt.localeCompare(a.changedAt) || b.revision.localeCompare(a.revision));
  const setting = records[0] || null;
  const revision = setting?.revision || hash('no-global-sprint-setting');
  return { revision, setting, history: records.slice(0, 30), legacyRecordCount: legacyRecords.length };
}

export function applySavedSprintSettings(projects, settings, { workItems = [] } = {}) {
  const dashboard = { projects, workItems };
  const scope = settings?.setting
    ? resolveSprintScope(dashboard, settings.setting)
    : legacyGlobalSprintScope(projects);
  if (scope.mode === 'all') {
    const resolved = resolveSprintScope(dashboard, settings.setting);
    return { projects: applyGlobalSprintScope(projects, resolved), scope: resolved };
  }
  return { projects: applyGlobalSprintScope(projects, scope), scope };
}

export function decorateSprintDashboard(dashboard, settings, { writable = false } = {}) {
  const applied = applySavedSprintSettings(dashboard.projects || [], settings, { workItems: dashboard.workItems || [] });
  const selectedSignature = scopeSignature(applied.scope);
  const collectedSignature = dashboard.sprintScope?.signature || scopeSignature(legacyGlobalSprintScope(dashboard.projects || []));
  const pendingInput = selectedSignature !== collectedSignature;
  const inputAt = Date.parse(dashboard.agentHandoff?.generatedAt || dashboard.generatedAt || '');
  const analysisAt = Date.parse(dashboard.ai?.generatedAt || '');
  const pendingAnalysis = pendingInput || (Number.isFinite(inputAt) && Number.isFinite(analysisAt) && analysisAt < inputAt);
  const output = {
    ...dashboard,
    projects: applied.projects,
    sprintSettings: {
      writable,
      revision: settings.revision,
      setting: settings.setting,
      history: settings.history,
      legacyRecordCount: settings.legacyRecordCount || 0,
      scope: applied.scope,
      pendingInput,
      pendingAnalysis,
    },
  };
  if (pendingAnalysis) {
    output.ai = { ...(dashboard.ai || {}), analysisStatus: !dashboard.ai || dashboard.ai.analysisStatus === 'not_run' ? 'not_run' : 'stale' };
    output.sourceHealth = { ...dashboard.sourceHealth, status: 'limited', sources: (dashboard.sourceHealth?.sources || []).map(source =>
      source.id === 'agent-analysis' ? { ...source, status: 'partial', analysisStatus: 'stale', successful: 0 } : source) };
  }
  output.workOverview = buildSprintOverview(output, applied.scope);
  return output;
}

export async function saveSprintSettings({ databaseId, dashboard, input, expectedRevision, query, create, now = new Date().toISOString(), uuid = randomUUID } = {}) {
  if (expectedRevision !== null && typeof expectedRevision !== 'string') throw error('설정 버전이 필요합니다.');
  const parsed = parseSprintInput(input);
  const before = await readSprintSettings({ databaseId, query });
  if (before.revision !== expectedRevision) throw error('다른 사용자가 설정을 변경했습니다. 최신 설정을 다시 불러오세요.', 409);

  const priorScope = before.setting
    ? resolveSprintScope(dashboard || {}, before.setting)
    : legacyGlobalSprintScope(dashboard?.projects || []);
  const nextComparable = { mode: parsed.mode, input: parsed.input, sprints: parsed.sprints };
  const priorComparable = { mode: priorScope.mode, input: priorScope.input, sprints: priorScope.mode === 'all' ? [] : priorScope.sprints };
  if (JSON.stringify(priorComparable) === JSON.stringify(nextComparable) && before.setting) return { settings: before, changed: false };

  const record = {
    kind: KIND,
    mode: parsed.mode,
    input: parsed.input,
    sprints: parsed.sprints,
    revision: uuid(),
    parentRevision: before.setting?.revision || null,
    previousInput: priorScope.input || '',
    changedAt: now,
  };
  create ||= (await import('./notion.mjs')).createDatabasePage;
  const serialized = JSON.stringify(record);
  const chunks = [];
  for (let i = 0; i < serialized.length; i += 1900) chunks.push(...text(serialized.slice(i, i + 1900)));
  await create(databaseId, {
    '이름': { title: text(`스프린트 설정 / 전체 프로젝트 / ${now}`) },
    '프로젝트명': { rich_text: text('대시보드 운영 설정') },
    '기준일': { date: { start: now } },
    run_id: { rich_text: text(`${SETTINGS_PREFIX}global:${record.revision}`) },
    payload: { rich_text: chunks },
  });
  const after = await readSprintSettings({ databaseId, query });
  if (after.setting?.revision !== record.revision) throw error('설정 저장 중 다른 변경이 감지됐습니다. 최신 설정과 변경 이력을 확인하세요.', 409);
  return { settings: after, changed: true };
}

export async function readSettingsBody(request, maxBytes = 16000) {
  if (request.body && typeof request.body === 'object') {
    if (Buffer.byteLength(JSON.stringify(request.body)) > maxBytes) throw error('요청이 너무 큽니다.', 413);
    return request.body;
  }
  let body = typeof request.body === 'string' ? request.body : '';
  if (!body) for await (const chunk of request) {
    body += chunk.toString();
    if (Buffer.byteLength(body) > maxBytes) throw error('요청이 너무 큽니다.', 413);
  }
  if (Buffer.byteLength(body) > maxBytes) throw error('요청이 너무 큽니다.', 413);
  try { const data = JSON.parse(body); if (!data || Array.isArray(data) || typeof data !== 'object') throw Error(); return data; }
  catch { throw error('JSON 요청 형식이 올바르지 않습니다.'); }
}

export function buildDashboardSyncCompleted(dashboard) {
  return {
    type: 'dashboardSyncCompleted',
    occurredAt: dashboard.generatedAt,
    notificationSent: false,
    payload: {
      generatedAt: dashboard.generatedAt,
      normalProjects: dashboard.projects.filter(project => project.managementStatus === 'normal').length,
      needsUpdateProjects: dashboard.projects.filter(project => project.managementStatus !== 'normal').length,
      overdueWorkItems: dashboard.workItems.filter(item => item.overdueDays > 0).length,
      issueCount: dashboard.validationIssues.length,
      dashboardUrl: dashboard.dashboardUrl || null,
    },
  };
}
